import React, { useState, useEffect } from 'react';
  import { 
    Truck, Calendar, MapPin, Phone, FileText, 
    CheckCircle, Clock, PlusCircle, ClipboardList, 
    Star, AlertTriangle, X, Users, CalendarDays, ChevronLeft, ChevronRight,
    ChevronDown, ChevronUp, Briefcase, Car, Wallet, CheckSquare, Shield, GripVertical, Activity,
    ArrowUpRight, ArrowDownRight, Landmark, CreditCard, DollarSign, ArrowRightLeft, ArrowUpDown,
    UserPlus, Camera, Upload, Edit, Ban, LogOut, Lock, Mail, Bell, User, Sparkles, Loader2, Copy, MessageSquareText,
    MessageCircle, Send, Package, Database, Download, History, Save, Search, Key, BarChart, TrendingUp, ListTodo,
    Eye, EyeOff, FolderOpen, Shirt, Smartphone, Award, Zap
  } from 'lucide-react';

  // --- FIREBASE BAĞLANTISI (ÖNİZLEME MODU) ---
  // NOT: Bu artifact/önizleme ortamında gerçek "firebase" paketi bulunmuyor.
  // Bu yüzden gerçek Firebase SDK'sının davranışını taklit eden, bellek içi
  // (in-memory) sahte bir Firestore + Auth katmanı kuruyoruz. Fonksiyon
  // isimleri ve imzaları (collection, doc, addDoc, onSnapshot, query, where,
  // orderBy, limit vb.) gerçek Firebase SDK'sıyla birebir aynı olduğu için,
  // canlıya geçerken sadece bu bloğu gerçek "firebase" importlarıyla
  // değiştirmek yeterli olur; geri kalan kodun HİÇBİRİNE dokunulmaz.

  const __store = {}; // path -> { docId: data }
  const __listeners = {}; // path -> Set of callback fonksiyonları

  const __notify = (path) => {
    if (__listeners[path]) {
      __listeners[path].forEach(cb => cb());
    }
  };

  const __genId = () => 'id_' + Date.now().toString(36) + '_' + Math.random().toString(36).substring(2, 9);

  // --- Yol (path) yardımcıları ---
  const __pathOf = (ref) => ref.__path;
  const __isCollectionRef = (ref) => ref.__type === 'collection';
  const __isDocRef = (ref) => ref.__type === 'doc';

  const collection = (db, ...segments) => ({
    __type: 'collection',
    __path: segments.join('/')
  });

  const doc = (db, ...segments) => {
    if (segments.length === 1 && segments[0].__type === 'collection') {
      // doc(collectionRef) şeklinde çağrılırsa otomatik id üret
      return { __type: 'doc', __path: segments[0].__path + '/' + __genId() };
    }
    return { __type: 'doc', __path: segments.join('/') };
  };

  const __splitDocPath = (path) => {
    const parts = path.split('/');
    const id = parts.pop();
    const colPath = parts.join('/');
    return { colPath, id };
  };

  const addDoc = async (colRef, data) => {
    const path = __pathOf(colRef);
    if (!__store[path]) __store[path] = {};
    const id = __genId();
    __store[path][id] = { ...data };
    __notify(path);
    return { id };
  };

  const setDoc = async (docRef, data, options = {}) => {
    const { colPath, id } = __splitDocPath(__pathOf(docRef));
    if (!__store[colPath]) __store[colPath] = {};
    if (options.merge) {
      __store[colPath][id] = { ...(__store[colPath][id] || {}), ...data };
    } else {
      __store[colPath][id] = { ...data };
    }
    // DÜZELTME: Hem koleksiyon dinleyicileri (onSnapshot(collection)) hem de
    // bu spesifik dokümanı dinleyen doc() dinleyicileri (onSnapshot(doc)) haberdar edilsin
    __notify(colPath);
    __notify(colPath + '/' + id);
    return { id };
  };

  const updateDoc = async (docRef, data) => {
    const { colPath, id } = __splitDocPath(__pathOf(docRef));
    if (!__store[colPath]) __store[colPath] = {};
    __store[colPath][id] = { ...(__store[colPath][id] || {}), ...data };
    __notify(colPath);
    __notify(colPath + '/' + id);
  };

  const deleteDoc = async (docRef) => {
    const { colPath, id } = __splitDocPath(__pathOf(docRef));
    if (__store[colPath]) delete __store[colPath][id];
    __notify(colPath);
    __notify(colPath + '/' + id);
  };

  const getDoc = async (docRef) => {
    const { colPath, id } = __splitDocPath(__pathOf(docRef));
    const data = __store[colPath] ? __store[colPath][id] : undefined;
    return {
      exists: () => data !== undefined,
      data: () => data,
      id
    };
  };

  // --- Basit sorgu (query/where/orderBy/limit) desteği ---
  const query = (colRef, ...constraints) => ({
    __type: 'query',
    __path: __pathOf(colRef),
    __constraints: constraints
  });

  const where = (field, op, value) => ({ __kind: 'where', field, op, value });
  const orderBy = (field, direction = 'asc') => ({ __kind: 'orderBy', field, direction });
  const limit = (n) => ({ __kind: 'limit', n });

  const __applyConstraints = (items, constraints) => {
    let result = items;
    constraints.filter(c => c.__kind === 'where').forEach(c => {
      result = result.filter(item => {
        const val = item.data[c.field];
        switch (c.op) {
          case '==': return val === c.value;
          case '!=': return val !== c.value;
          case '>=': return val >= c.value;
          case '<=': return val <= c.value;
          case '>': return val > c.value;
          case '<': return val < c.value;
          case 'array-contains': return Array.isArray(val) && val.includes(c.value);
          case 'in': return Array.isArray(c.value) && c.value.includes(val);
          default: return true;
        }
      });
    });
    const orderConstraint = constraints.find(c => c.__kind === 'orderBy');
    if (orderConstraint) {
      result = [...result].sort((a, b) => {
        const av = a.data[orderConstraint.field];
        const bv = b.data[orderConstraint.field];
        if (av < bv) return orderConstraint.direction === 'desc' ? 1 : -1;
        if (av > bv) return orderConstraint.direction === 'desc' ? -1 : 1;
        return 0;
      });
    }
    const limitConstraint = constraints.find(c => c.__kind === 'limit');
    if (limitConstraint) {
      result = result.slice(0, limitConstraint.n);
    }
    return result;
  };

  const __getItemsForRef = (ref) => {
    const path = ref.__type === 'query' ? ref.__path : __pathOf(ref);
    const raw = __store[path] || {};
    let items = Object.keys(raw).map(id => ({ id, data: raw[id] }));
    if (ref.__type === 'query') {
      items = __applyConstraints(items, ref.__constraints);
    }
    return { path, items };
  };

  const getDocs = async (ref) => {
    const { items } = __getItemsForRef(ref);
    return {
      docs: items.map(it => ({
        id: it.id,
        data: () => it.data,
        exists: () => true
      })),
      empty: items.length === 0,
      size: items.length,
      forEach: (cb) => items.forEach(it => cb({ id: it.id, data: () => it.data }))
    };
  };

  const onSnapshot = (ref, onNext, onError) => {
    const path = ref.__type === 'query' ? ref.__path : __pathOf(ref);
    const callback = () => {
      try {
        if (ref.__type === 'doc') {
          // YENİ/DÜZELTME: Tekil doküman (doc()) dinlemeleri için gerçek Firestore'daki
          // gibi exists()/data() metotlarına sahip bir DocumentSnapshot döndürülür.
          // Önceden bu ayrım yapılmıyordu ve koleksiyon tipi (.docs/.empty) döndürülüyordu;
          // bu da docSnap.exists() çağrılarında hataya ve "Bulut Verileri Eşitleniyor..."
          // ekranında sonsuz beklemeye neden oluyordu.
          const { colPath, id } = __splitDocPath(path);
          const data = __store[colPath] ? __store[colPath][id] : undefined;
          onNext({
            exists: () => data !== undefined,
            data: () => data,
            id,
            metadata: { hasPendingWrites: false }
          });
          return;
        }
        const { items } = __getItemsForRef(ref);
        const snapshot = {
          docs: items.map(it => ({
            id: it.id,
            data: () => it.data,
            exists: () => true
          })),
          empty: items.length === 0,
          size: items.length,
          metadata: { hasPendingWrites: false },
          forEach: (cb) => items.forEach(it => cb({ id: it.id, data: () => it.data }))
        };
        onNext(snapshot);
      } catch (err) {
        if (onError) onError(err);
      }
    };
    if (!__listeners[path]) __listeners[path] = new Set();
    __listeners[path].add(callback);
    // İlk veriyi hemen gönder
    callback();
    // unsubscribe fonksiyonu döndür
    return () => { __listeners[path] && __listeners[path].delete(callback); };
  };

  // --- Sahte Auth Katmanı ---
  const __authListeners = new Set();
  let __currentAuthUser = null;

  const getAuth = () => ({ __type: 'mockAuth' });

  const signInAnonymously = async () => {
    __currentAuthUser = { uid: 'preview-anon-' + __genId() };
    __authListeners.forEach(cb => cb(__currentAuthUser));
    return { user: __currentAuthUser };
  };

  const signInWithCustomToken = async (auth, token) => {
    __currentAuthUser = { uid: 'preview-token-' + __genId() };
    __authListeners.forEach(cb => cb(__currentAuthUser));
    return { user: __currentAuthUser };
  };

  const onAuthStateChanged = (auth, callback) => {
    __authListeners.add(callback);
    // Önizleme modunda otomatik olarak anonim oturum açılmış say
    setTimeout(() => {
      if (!__currentAuthUser) __currentAuthUser = { uid: 'preview-anon-' + __genId() };
      callback(__currentAuthUser);
    }, 50);
    return () => __authListeners.delete(callback);
  };

  const auth = getAuth();
  const db = { __type: 'mockDb' };
  const appId = 'sembol-crm-onizleme';

  const __memoryStorage = {};
  const localStorage = {
    getItem: (k) => (k in __memoryStorage ? __memoryStorage[k] : null),
    setItem: (k, v) => { __memoryStorage[k] = String(v); },
    removeItem: (k) => { delete __memoryStorage[k]; },
    clear: () => { Object.keys(__memoryStorage).forEach(k => delete __memoryStorage[k]); }
  };

  // --- ÖNİZLEME İÇİN VARSAYILAN SİSTEM YÖNETİCİSİ ---
