  ['jobs', 'personnelList', 'vehicles', 'materials'].forEach((colName) => {
    const path = `artifacts/${appId}/public/data/${colName}`;
    if (!__store[path]) __store[path] = {};
    // YENİ: Malzemeler yüklenirken kopyaları (aynı isimden onlarca kayıt) 5 ana malzemeye indir,
    // stokları topla. Böylece önizleme de temiz başlar; ekip kurma tahtasındaki Streç/Bant/Poşet/Kağıt/Koli dışında kayıt kalmaz.
    if (colName === 'materials') {
      const norm = (s) => (s || '').toLocaleLowerCase('tr-TR');
      const mainMats = [
        { name: 'Streç', category: 'Ambalaj Malzemesi', unit: 'Rulo', key: 'streç' },
        { name: 'Bant', category: 'Ambalaj Malzemesi', unit: 'Adet', key: 'bant' },
        { name: 'Poşet', category: 'Ambalaj Malzemesi', unit: 'Adet', key: 'poşet' },
        { name: 'Kağıt', category: 'Ambalaj Malzemesi', unit: 'Kg', key: 'kağıt' },
        { name: 'Koli', category: 'Ambalaj Malzemesi', unit: 'Adet', key: 'koli' }
      ];
      const source = __backupData[colName] || [];
      mainMats.forEach((mat, idx) => {
        const matches = source.filter(m => norm(m.name).includes(mat.key));
        const totalStock = matches.reduce((sum, m) => sum + (parseFloat(m.stock) || 0), 0);
        const fixedId = `material_${mat.key}`; // sabit ID → her yüklemede tek kayıt
        __store[path][fixedId] = { name: mat.name, category: mat.category, unit: mat.unit, stock: String(totalStock) };
      });
      return; // materials için varsayılan yüklemeyi atla
    }
    (__backupData[colName] || []).forEach((item) => {
      const { id, ...rest } = item;
      __store[path][id] = rest;
    });
  });


